/**
 * A stored rich-text document drawn through the vocabulary (`design/components/rich-text-content.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Keyed,
  RICH_TEXT_STOP,
  agentMember,
  agentPress,
  claimSlot,
  createCell,
  createDerived,
  drawSlot,
  elementRef,
  enterToolbar,
  followSelectionBar,
  holdToolbarEscape,
  mapRichTextSelection,
  ownerContext,
  placeSelectionBar,
  provide,
  richTextAnnotations,
  richTextDrawing,
  richTextKeyedAnnotation,
  richTextPressedAnnotation,
  richTextSelectionBox,
  scope,
  serializeRichText,
  slotDraws,
  syncToolbarStop,
  toolbarFocusIn,
  toolbarFocusOut,
  toolbarKeydown,
  toolbarPress,
  toolbarStop,
  watchEffect,
  type Defaults,
  type RichTextDocument,
  type RichTextEntity,
  type RichTextRange,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import selectionBar from '@polymorph/recipes/controls/selection-bar.module.css'
import RichTextContentBlocks from './RichTextContentBlocks'

export type RichTextContentSize = NonNullable<RichTextContentProps['size']>

export interface RichTextContentSelection {
  range: RichTextRange
  text: string
}

export interface RichTextContentMessages {
  selectionBar?: string
  selectionBarReady?: string
}

export interface RichTextContentProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  /**
   * The app's rendering of an entity: a Link to the person's page, a HoverCard with their card.
   * `undefined` draws the entity token, so an app can draw one kind itself and leave the others
   * as tokens.
   */
  entity?: (arg: RichTextEntity) => JSX.Element
  /**
   * The page level the document's level 1 heading is drawn at. Each deeper level adds one, up to
   * 4. Default 2, one level under the page's title.
   */
  headingLevel?: 2 | 3 | 4
  /**
   * The selection bar's words, in the app's language.
   */
  messages?: RichTextContentMessages
  /**
   * A press on a drawn annotation. Without it the highlights take no press and no focus.
   */
  onAnnotationSelect?: (id: string) => void
  /**
   * The app's router, handed to every Link the document draws (`link.md`).
   */
  onNavigate?: (href: string) => void
  /**
   * The app's controls for the reader's selected text, in a bar at the selection.
   */
  selectionActions?: (arg: RichTextContentSelection) => JSX.Element
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The stored document. Any JSON is read as far as it can be; what is not a document draws
   * nothing.
   */
  value: RichTextDocument
}

/** What RichTextContent hands its compound parts. */
export interface RichTextContentOwner {
  readonly size: Exclude<RichTextContentProps['size'], undefined>
  readonly pressable: unknown
  readonly routes: unknown
  readonly navigate: unknown
  readonly entityNode: unknown
}

/** A stored rich-text document drawn through the vocabulary. */
export default function RichTextContent(given: RichTextContentProps): JSX.Element {
  const props = mergeProps(
    { size: 'md' } as Defaults<RichTextContentProps, 'size'>,
    claimSlot(given),
  )
  return scope(() => {
    provide(ownerContext<RichTextContentOwner>('RichTextContent'), {
      get size() {
        return props.size
      },
      get pressable() {
        return pressable.value
      },
      get routes() {
        return routes.value
      },
      get navigate() {
        return navigate.value
      },
      get entityNode() {
        return entityNode.value
      },
    })
    const selected = createCell({
      now: null as { range: RichTextRange; text: string; key: string } | null,
      last: null as { range: RichTextRange; text: string; key: string } | null,
    })
    const selecting = createCell(false)
    const dismissed = createCell(null as string | null)
    const barFocus = createCell(false)
    const said = createCell({ text: '', at: 0 })
    const barHeard = createCell(false)
    const bar = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const status = elementRef<HTMLElement>()
    const held = createDerived(() => ({
      range: null as Range | null,
      cameFrom: null as HTMLElement | null,
      restoring: false,
    }))
    const say = createDerived(() => ({
      selectionBar: props.messages?.selectionBar ?? 'Selection',
      selectionBarReady:
        props.messages?.selectionBarReady ?? 'Controls for the selection are available: Alt+F10',
    }))
    const pressable = createDerived(() => props.onAnnotationSelect !== undefined)
    const routes = createDerived(() => props.onNavigate !== undefined)
    const navigate = createDerived(() => (href: string) => props.onNavigate?.(href))
    const entityNode = createDerived(() => (drawn: RichTextEntity) => drawSlot(props.entity, drawn))
    const mapped = createDerived(() => !!(props.selectionActions !== undefined))
    const appDraws = createDerived(() => (drawn: RichTextEntity) => slotDraws(props.entity, drawn))
    const drawing = createDerived(() =>
      richTextDrawing(props.value, {
        headingLevel: props.headingLevel,
        annotations: props.annotations,
        activeAnnotation: props.activeAnnotation,
        pressable: pressable.value,
        positions: mapped.value,
        appDraws: appDraws.value,
      }),
    )
    const drawn = createDerived(
      () => (id: string) => props.annotations === undefined || props.annotations.includes(id),
    )
    const offering = createDerived(() => mapped.value && !drawing.value.empty)
    const docKey = createDerived(() =>
      offering.value ? serializeRichText(drawing.value.value) : '',
    )
    const shown = createDerived(
      () => selected.value.now ?? (barFocus.value ? selected.value.last : null),
    )
    const barOpen = createDerived(
      () =>
        offering.value &&
        shown.value !== null &&
        !selecting.value &&
        dismissed.value !== shown.value.key,
    )
    const content = createDerived(() => selected.value.now ?? selected.value.last)
    const announce = createDerived(() => (words: string) => {
      said.value = { text: words, at: said.value.at + 1 }
    })
    const outside = createDerived(
      () =>
        (node: Node): Element | null =>
          [bar.value, status.value].find((part) => part?.contains(node) === true) ?? null,
    )
    const updateSelection = createDerived(() => () => {
      const found = root.value
        ? mapRichTextSelection(root.value, outside.value, drawing.value.value)
        : null
      if (found !== null) held.value.range = found.dom
      // A dismissal holds for one selection: once it collapses, the next one brings the bar back.
      else dismissed.value = null
      if (found === null) {
        if (selected.value.now !== null) selected.value = { now: null, last: selected.value.last }
        return
      }
      if (selected.value.now?.key === found.key && selected.value.now.text === found.text) return
      const mapping = { range: found.range, text: found.text, key: found.key }
      selected.value = { now: mapping, last: mapping }
    })
    const followSelection = createDerived(() => (element: HTMLElement) => {
      const page = element.ownerDocument
      const update = () => updateSelection.value()
      page.addEventListener('selectionchange', update)
      return () => page.removeEventListener('selectionchange', update)
    })
    const releaseSelecting = createDerived(() => (element: HTMLElement) => {
      const view = element.ownerDocument.defaultView
      const release = () => {
        selecting.value = false
      }
      view?.addEventListener('pointerup', release, true)
      view?.addEventListener('pointercancel', release, true)
      return () => {
        view?.removeEventListener('pointerup', release, true)
        view?.removeEventListener('pointercancel', release, true)
      }
    })
    const holdKeys = createDerived(() => (element: HTMLElement) => {
      const view = element.ownerDocument.defaultView
      const keys = (event: KeyboardEvent) => {
        const target = event.target
        if (event.isComposing || !(target instanceof Node)) return
        if (bar.value?.contains(target) === true) return
        const page = element.ownerDocument
        if (target !== page.body && target !== page.documentElement && !element.contains(target))
          return
        if (event.key === 'Escape') {
          event.preventDefault()
          if (shown.value !== null) dismissed.value = shown.value.key
        } else if (event.key === 'F10' && event.altKey) {
          event.preventDefault()
          enterToolbar(bar.value, barStops.value)
        }
      }
      view?.addEventListener('keydown', keys, true)
      return () => view?.removeEventListener('keydown', keys, true)
    })
    const restoreSelection = createDerived(() => () => {
      const range = held.value.range
      const selection = root.value?.ownerDocument.getSelection()
      if (range === null || selection === null || selection === undefined || !selection.isCollapsed)
        return
      selection.removeAllRanges()
      selection.addRange(range)
    })
    const leaveBar = createDerived(() => () => {
      if (shown.value !== null) dismissed.value = shown.value.key
      held.value.restoring = true
      restoreSelection.value()
    })
    const giveFocusBack = createDerived(() => () => {
      const to = held.value.cameFrom
      held.value.cameFrom = null
      const active = bar.value?.ownerDocument.activeElement
      if (to !== null && to.isConnected && bar.value?.contains(to) !== true)
        to.focus({ preventScroll: true })
      else if (active instanceof HTMLElement && bar.value?.contains(active) === true) active.blur()
      if (held.value.restoring) restoreSelection.value()
      held.value.restoring = false
    })
    const barLeave = createDerived(() => (event: FocusEvent) => {
      const to = event.relatedTarget
      if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
      barFocus.value = false
      // A leaving bar is inert, and a browser that moves focus off it does so here.
      if (bar.value?.inert === true) giveFocusBack.value()
    })
    const cameFrom = createDerived(() => (event: FocusEvent) => {
      const from = event.relatedTarget
      if (from instanceof HTMLElement && bar.value?.contains(from) === true) return
      held.value.cameFrom = from instanceof HTMLElement ? from : null
    })
    const documentChanged = createDerived(() => () => {
      selected.value = { now: null, last: null }
      held.value.range = null
      const selection = root.value?.ownerDocument.getSelection()
      if (
        root.value === null ||
        root.value === undefined ||
        selection === null ||
        selection === undefined
      )
        return
      if (selection.rangeCount === 0 || selection.isCollapsed) return
      const range = selection.getRangeAt(0)
      if (root.value.contains(range.startContainer) || root.value.contains(range.endContainer))
        selection.collapseToEnd()
    })
    const measure = createDerived(() => () => {
      const selection = root.value?.ownerDocument.getSelection()
      if (root.value && selection && selection.rangeCount > 0) {
        const range = selection.getRangeAt(0)
        if (!range.collapsed && root.value.contains(range.commonAncestorContainer))
          return richTextSelectionBox(range)
      }
      return held.value.range === null ? null : richTextSelectionBox(held.value.range)
    })
    const placeBar = createDerived(() => () => placeSelectionBar(bar.value, measure.value()))
    const barStops = createDerived(() => toolbarStop())
    const holdEscapeIn = createDerived(() => (element: HTMLElement) => {
      const view = element.ownerDocument.defaultView
      return view === null ? () => {} : holdToolbarEscape(view, () => bar.value)
    })
    const pressed = createDerived(() => (event: MouseEvent) => {
      const id = richTextPressedAnnotation(
        event.currentTarget as Element,
        event.target,
        event.detail,
        bar.value,
      )
      if (id !== null) props.onAnnotationSelect?.(id)
    })
    const keyed = createDerived(() => (event: KeyboardEvent, phase: 'down' | 'up') => {
      const id = richTextKeyedAnnotation(event, phase)
      if (id !== null) props.onAnnotationSelect?.(id)
    })
    const pressDown = createDerived(() => (event: PointerEvent) => {
      if (!(event.target instanceof Node) || bar.value?.contains(event.target) !== true)
        selecting.value = true
    })
    const barPresent = usePresence(
      () => barOpen.value,
      () => bar.value,
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = offering.value && root.value ? followSelection.value(root.value) : () => {}
      release1 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => offering.value),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = selecting.value && root.value ? releaseSelecting.value(root.value) : () => {}
      release2 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => selecting.value),
      effect2,
      true,
    )
    onCleanup(() => release2?.())
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const ran = barOpen.value && root.value ? holdKeys.value(root.value) : () => {}
      release3 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => barOpen.value),
      effect3,
      true,
    )
    onCleanup(() => release3?.())
    const effect4 = () => {
      documentChanged.value()
    }
    watchEffect(
      createMemo(() => docKey.value),
      effect4,
      false,
    )
    const effect5 = () => {
      void (
        !barOpen.value &&
        bar.value?.contains(bar.value.ownerDocument.activeElement) === true &&
        giveFocusBack.value()
      )
    }
    watchEffect(
      createMemo(() => barOpen.value),
      effect5,
      false,
    )
    const effect6 = () => {
      void (
        barOpen.value &&
        !barHeard.value &&
        ((barHeard.value = true), announce.value(say.value.selectionBarReady))
      )
    }
    watchEffect(
      createMemo(() => barOpen.value),
      effect6,
      true,
    )
    let release7: (() => void) | undefined
    const effect7 = () => {
      release7?.()
      const run = () => {
        syncToolbarStop(bar.value, barStops.value)
      }
      const mutation =
        typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
      for (const element of [bar.value])
        if (element)
          mutation?.observe(element, {
            childList: true,
            characterData: true,
            subtree: true,
            attributeFilter: ['disabled', 'aria-disabled', 'hidden', 'inert'],
          })
      release7 = () => {
        mutation?.disconnect()
      }
      run()
    }
    watchEffect(
      createMemo(() => barPresent()),
      effect7,
      true,
    )
    onCleanup(() => release7?.())
    let release8: (() => void) | undefined
    const effect8 = () => {
      release8?.()
      const ran = barPresent() && bar.value ? holdEscapeIn.value(bar.value) : () => {}
      release8 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => barPresent()),
      effect8,
      true,
    )
    onCleanup(() => release8?.())
    const effect9 = () => {
      void (barOpen.value && placeBar.value())
    }
    watchEffect(
      createMemo(() => [barOpen.value, selected.value]),
      effect9,
      true,
    )
    let release10: (() => void) | undefined
    const effect10 = () => {
      release10?.()
      const ran =
        barOpen.value && bar.value ? followSelectionBar(bar.value, placeBar.value) : () => {}
      release10 = () => {
        ran()
      }
    }
    watchEffect(
      createMemo(() => barOpen.value),
      effect10,
      true,
    )
    onCleanup(() => release10?.())
    let release11: (() => void) | undefined
    const effect11 = () => {
      release11?.()
      const ran = !(props.onAnnotationSelect !== undefined)
        ? () => {}
        : agentMember({
            member: 'RichTextContent',
            element: () => root.value,
            state: () => ({
              annotations: richTextAnnotations(drawing.value.value)
                .filter((annotation) => drawn.value(annotation.id))
                .map((annotation) => ({
                  id: annotation.id,
                  label: annotation.text,
                  ...(drawing.value.stops.includes(annotation.id) ? {} : { disabled: true }),
                })),
              active: richTextAnnotations(drawing.value.value).some(
                (annotation) =>
                  drawn.value(annotation.id) && annotation.id === props.activeAnnotation,
              )
                ? (props.activeAnnotation ?? null)
                : null,
            }),
            actions: {
              select: {
                argument: 'id',
                run: (value) =>
                  (() => {
                    const stop = Array.from(
                      root.value?.querySelectorAll(RICH_TEXT_STOP) ?? [],
                    ).find((element) => element.getAttribute('data-annotation-id') === value)
                    if (stop === undefined)
                      throw new Error('That annotation has no highlight to press.')
                    agentPress(stop)
                  })(),
              },
            },
          })
      release11 = () => {
        ran()
      }
    }
    onMount(effect11)
    onCleanup(() => release11?.())
    return (
      <div
        class={styles.root}
        data-size={props.size}
        data-empty={drawing.value.empty ? '' : undefined}
        data-member="rich-text-content"
        onclick={($event: MouseEvent) => pressable.value && pressed.value($event)}
        onkeydown={($event: KeyboardEvent) => pressable.value && keyed.value($event, 'down')}
        onkeyup={($event: KeyboardEvent) => pressable.value && keyed.value($event, 'up')}
        onpointerdown={($event: PointerEvent) => offering.value && pressDown.value($event)}
        ref={root.attach}
      >
        {!drawing.value.empty ? <RichTextContentBlocks blocks={drawing.value.blocks} /> : null}
        {offering.value && barPresent() ? (
          <div
            class={selectionBar.bar}
            role="toolbar"
            aria-label={say.value.selectionBar}
            data-state={!barOpen.value ? 'closed' : undefined}
            inert={!barOpen.value ? true : undefined}
            onkeydown={($event: KeyboardEvent) =>
              toolbarKeydown(
                $event.currentTarget as HTMLElement,
                $event,
                barStops.value,
                leaveBar.value,
              )
            }
            onfocusin={($event: FocusEvent) => (
              toolbarFocusIn($event.currentTarget as HTMLElement, $event, barStops.value),
              (barFocus.value = true)
            )}
            onfocusout={($event: FocusEvent) => (
              toolbarFocusOut($event.currentTarget as HTMLElement, $event, barStops.value),
              barLeave.value($event)
            )}
            onmousedown={($event: MouseEvent) =>
              toolbarPress($event.currentTarget as HTMLElement, $event)
            }
            ref={bar.attach}
          >
            {/* actions */}
            <div class={styles.actions} onfocusin={($event: FocusEvent) => cameFrom.value($event)}>
              {content.value !== null
                ? props.selectionActions?.({ range: content.value.range, text: content.value.text })
                : null}
            </div>
          </div>
        ) : null}
        {offering.value ? (
          <div class={styles.status} role="status" aria-live="polite" ref={status.attach}>
            {said.value.text !== '' ? (
              <Keyed by={said.value.at}>{() => <span>{said.value.text}</span>}</Keyed>
            ) : null}
          </div>
        ) : null}
      </div>
    )
  })
}
